def msg_level_of(text: str) -> str:
    """按文案前缀猜级别（老的提示语都带 ✅/❌/⚠️ 前缀，不必逐处改调用）。
        English:
    Guess the level from the text prefix (old prompts all have ✅/❌/⚠️ prefixes, no need to change
    call sites one by one).
    """
    s = str(text or '').lstrip()
    if s.startswith('❌'):
        return 'error'
    if s.startswith('⚠'):
        return 'warn'
    if s.startswith('✅'):
        return 'ok'
    return 'info'


def mk_btn(label: str, on_click=None, primary: bool = True, width: int = None,
           height: int = None, danger: bool = False) -> ft.Control:
    """紧凑按钮。

    `height` 默认 `BTN_H`。**和输入框同一行时传 `SET_H`** ——
    一个 34 的按钮挨着一个 42 的输入框，看着就是"没对齐"。

    `danger=True` 换成**朱砂底 + 纸白字**：删除这类不可逆的操作必须一眼看出来
    跟旁边那几个按钮不是一类。（**别把 `color` 写在里面的 `Text` 上** ——
    那样按钮自己的 `color` 就透不进去了，改配色要改两处。）
    
        English:
    Compact button.
        `height` defaults to `BTN_H`. **When on the same row as an input, pass `SET_H`** --
        a 34-high button next to a 42-high input just looks "misaligned".
        `danger=True` switches to **vermilion background + paper-white text**: irreversible operations like delete must be obvious at a glance
        that they are not the same kind as the buttons next to them. (**Don't put `color` on the inner `Text`** --
        that way the button's own `color` won't show through, and changing the palette means changing two places.)
    """
    txt = ft.Text(label, size=BTN_FS)
    style = ft.ButtonStyle(padding=CP_BTN)
    h = height or BTN_H
    if danger:
        return ft.FilledButton(content=txt, on_click=on_click,
                               height=h, width=width, style=style,
                               bgcolor=DANGER, color=C['paper_hi'])
    if primary:
        return ft.FilledButton(content=txt, on_click=on_click,
                               height=h, width=width, style=style,
                               bgcolor=C['border'], color=C['gold'])
    return ft.TextButton(content=txt, on_click=on_click,
                         height=h, width=width, style=style)


#: 「生成 / 更新」这类**要花 token 的重活按钮**的高度（比普通 `BTN_H=28` 高一头，
#: 一眼看出它不是排版按钮）。
# [EN] Height of the "generate / refresh" heavy-lifting buttons (a head taller than BTN_H=28).
GEN_BTN_H = 38


def mk_gen_btn(label: str, on_click=None, tooltip: str = '') -> ft.FilledButton:
    """**重活按钮**：实心赭金底 + 纸白字 + 加粗 + 加宽内边距。

    与 `mk_btn(primary=True)`（淡金底 + 赭金字）是**两个档**，别混用：
      · `mk_btn(primary=True)` = 「一行里的主要动作」（保存 / 确定），要和周围同高；
      · 这个 = **整屏就这一件要紧事**（推演结果里的「生成 / 更新」，点一下要等
        模型跑几十秒、还要花钱）。用户 2026-10-29 的原话就是「让他们更明显一些」——
        「更明显」不能靠换个淡一点的颜色，得**同时动三样**：底色实心、字号 +1、加粗。
    ⚠ 文字仍走 `ft.Text` 内容（`set_btn_text` 依赖 `content` 是 `ft.Text` 才改得动，
      见那里）；不要把文字写成裸字符串。
    ⚠ 禁用态（生成中）由 Flet 自动压暗，不用自己换色 —— 自己换会和 hover 打架。

        English:
    Heavy-lifting button: solid ochre-gold fill + paper-white bold text + wide padding.
    Two distinct tiers vs `mk_btn(primary=True)`: that one is "the main action in a row"
    (same height as its neighbours); this one is **the one thing that matters on the screen**
    (the results dialog's 生成/更新 -- one click means tens of seconds and real money).
    "More obvious" cannot be achieved by a slightly different colour alone: fill + size + weight.
    """
    txt = ft.Text(label, size=BTN_FS + 1, weight=ft.FontWeight.BOLD)
    return ft.FilledButton(
        content=txt, on_click=on_click, height=GEN_BTN_H,
        style=ft.ButtonStyle(padding=ft.Padding(22, 0, 22, 0)),
        bgcolor=C['gold'], color=C['paper_hi'],
        tooltip=tooltip or None)


def mk_icon_btn(icon, on_click=None, *, size: int = 26, height: int = 22,
                danger: bool = True, tooltip: str = '') -> ft.Container:
    """**图标小按钮**：自己画一个圆角底 + 居中一个 Material 图标。

    为什么不直接 `mk_btn('🗑')`：那个 emoji 是**彩色字形**，宽度和基线由字体决定，
    塞进 30px 宽的 `FilledButton` 里会**溢出背景** —— 用户的原话就是
    「删除的垃圾桶图标没在红色背景里」。`ft.Icon` 是**单色矢量**（跟着 `color` 走、
    尺寸可控），再配 `alignment` 保证居中，几何完全由我们说了算。

    ⚠ 里面那个 `ft.Icon` **不要**再挂 `on_click`（容器已经接了）——
    两层都接的话点击会走到两个回调里。
    
        English:
    **Small icon button**: draw your own rounded background + a centered Material icon.
        Why not just `mk_btn('🗑')`: that emoji is a **color glyph**, its width and baseline determined by the font,
        and stuffing it into a 30px-wide `FilledButton` will **overflow the background** -- the user's exact words were
        "the delete trash icon isn't inside the red background". `ft.Icon` is a **monochrome vector** (follows `color`,
        controllable size), and with `alignment` to guarantee centering, the geometry is entirely up to us.
        ⚠ The inner `ft.Icon` should **not** also have `on_click` attached (the container already handles it) --
        if both layers handle it, the click will go into two callbacks.
    """
    return ft.Container(
        content=ft.Icon(icon, size=max(10, size - 11),
                        color=C['paper_hi'] if danger else C['text']),
        width=size, height=height, border_radius=4,
        bgcolor=DANGER if danger else C['panel'],
        border=make_border(1, DANGER if danger else C['border']),
        alignment=ft.Alignment(0, 0),
        on_click=on_click,
        tooltip=(tooltip or None),
    )


def mk_dashed_frame(child: ft.Control, *, color: str, dashes: int = 5,
                    thick: float = 2, pad: float = 2) -> ft.Stack:
    """给 `child` 套一个**真正的虚线框**（2026-10-21，回收站里的"只是借来撑树"的节点）。

    用户原话：「会有一些作为父节点的节点也显示在这里，但实际上没有被删除，对于这样的
    节点，请用一些办法标记出来，**比如用虚线框起来**。」

    ★★★ 为什么不能用 `border=…` 画虚线：**Flutter 的 `BorderStyle` 只有 `none` 和
      `solid`**（本机实测：`list(ft.BorderStyle)` 就这两个），`ft.BorderSide(style=…)`
      根本没有 `dashed`。所以虚线只能**自己拼**。

    ★ 怎么拼（这是这段唯一的手艺）：
      · 一条虚线 = 一串小方块，**它们之间的空档用 `expand` 的透明容器**。
        `Row`/`Column` 里的 `expand` 会自动分配剩余空间 —— 于是**不用知道宽度/高度**
        也能均匀铺满。若用固定像素算间距，就得先知道尺寸，而这里的尺寸取决于
        字号、DPI、标题长短（本项目在这上面栽过好几次）。
      · 竖边放在 `Stack` 的**定位层**（`top/bottom=0`）⇒ 高度被上面那层内容定住，
        `Column` 里的 `expand` 因此可以是"有界的"，才铺得开。
      · 四边各 5 段、2px 粗：再密看不出是虚线，再疏会像四个角标。

    ⚠ 这是**纯装饰**：不含任何交互，也不改 `child` 的任何属性 —— 所以它能套在
      任何卡片外面，不需要卡片配合。

        English:
    Wrap `child` in a **genuine dashed frame** (2026-10-21; for recycle-bin nodes that are only
    borrowed to keep the tree's shape).
    User's words: "...mark them somehow, **e.g. outline them with a dashed border**."
    ★★★ Why `border=...` cannot do it: **Flutter's `BorderStyle` only has `none` and `solid`**
      (measured here: `list(ft.BorderStyle)` is exactly those two); `ft.BorderSide(style=...)` has no
      `dashed` at all. So the dashes must be assembled by hand.
    ★ How (the only trick here): one dashed edge = a string of small blocks with **`expand`ing
      transparent containers in between**. `expand` distributes the leftover space automatically, so
      the dashes fill evenly **without knowing the width/height**. Computing gaps from fixed pixels
      would require the size up front, and the size depends on font size, DPI and title length (this
      project has been bitten by that repeatedly).
      Vertical edges sit on the `Stack`'s **positioned layer** (`top/bottom=0`) so their height is
      pinned by the content, which is what makes `expand` bounded inside the `Column`.
      Five 2px dashes per edge: denser stops reading as dashed, sparser looks like corner marks.
    ⚠ Purely decorative: no interaction, and it does not touch any property of `child` -- so it wraps
      any card without the card cooperating.
    """
    def _rule(horizontal: bool) -> ft.Control:
        parts: list[ft.Control] = []
        for i in range(max(1, dashes)):
            if i:
                parts.append(ft.Container(expand=True))
            parts.append(ft.Container(width=8, height=thick, bgcolor=color)
                         if horizontal else
                         ft.Container(width=thick, height=8, bgcolor=color))
        return (ft.Row(parts, spacing=0) if horizontal
                else ft.Column(parts, spacing=0))

    return ft.Stack([
        # 非定位子：由它决定这个框的尺寸（外边距给虚线让位）
        # [EN] The non-positioned child decides the frame's size (margin makes room for the dashes)
        ft.Container(content=child, margin=ft.Margin(thick, thick, thick, thick)),
        ft.Container(left=pad, right=pad, top=0, height=thick,
                     content=_rule(True)),
        ft.Container(left=pad, right=pad, bottom=0, height=thick,
                     content=_rule(True)),
        ft.Container(left=0, top=pad, bottom=pad, width=thick,
                     content=_rule(False)),
        ft.Container(right=0, top=pad, bottom=pad, width=thick,
                     content=_rule(False)),
    ])


# ⚠⚠ 2026-10-22：这个函数**以前也叫 `mk_check`**，与本文件上面那个
#   `mk_check(label, value, ...) -> ft.Checkbox` **重名**。Python 里后定义覆盖先定义，
#   于是上面那个成了死代码、而全部**按位置**调用的地方（9 处：同意修复/同意发送正文/
#   AI 模型能力勾选/导出选项…）都变成 `mk_check() takes 0 positional arguments but 2 were given`
#   —— 界面上那些复选框全崩（实测：「AI 模型配置」里新建模型直接打不开）。
#   ⇒ 自绘这个改名 `mk_node_check`（它本来就是给树节点用的），老名字留给普通复选框。
# [EN] ⚠⚠ 2026-10-22: this function **used to be called `mk_check` too**, clashing with the
# [EN] `mk_check(label, value, ...) -> ft.Checkbox` above. Python lets the later definition win, so
# [EN] the earlier one became dead code and every **positional** call site (9 of them: consent
# [EN] checkboxes, AI capability ticks, export options...) raised "takes 0 positional arguments but
# [EN] 2 were given" -- those checkboxes were dead (measured: the model editor would not open).
# [EN] => The self-drawn one is renamed `mk_node_check` (it is for tree nodes anyway) and the old
# [EN] name goes back to meaning a plain checkbox.
def mk_node_check(*, checked: bool = False, on_change=None,
                  tooltip: str = '') -> tuple[ft.Container, dict]:
    """一个**自绘复选框**（22×22，空心方框 ⇄ 打勾），返回 `(控件, 状态)`。

    ★ 为什么不用 `ft.Checkbox`：它的点击区和内边距由 Material 决定，塞进一行
      22px 高的标题里会把行撑高、还会把行内其它按钮挤偏。这里与
      `mk_icon_btn` 同一套做法（自绘容器 + 居中 `ft.Icon`），几何完全可控。
    ★ 返回 `(控件, state)`：`state['checked']` 是唯一事实来源。四个操作：
        · `state['set'](bool)`   相当于**用户点了一下**（会回调 `on_change`，受锁影响）
        · `state['force'](bool)` **直接改状态、不回调**（级联用；见下面 `lock`）
        · `state['lock'](bool)`  锁住/解锁：锁住时**点不动**、图标画成灰色
        · `state['locked']`      现在锁着没有

    ★★★ 为什么要 `lock`（2026-10-21 用户：「存放的复选框选中某个节点，其子节点会被自动
      选中，而且在父节点被选中的时候，所有子节点的复选框是灰色的，无法被取消选中。
      要选择子节点，只能够取消父节点选中，然后在子节点里选择」）：
      这是**树的语义** —— 删父节点本来就必然带走全部子节点（`TRASH.descendants`），
      所以让子节点"看起来可选"是骗人的。锁灰 = 把"它一定会被删"画出来。
      ⚠ 锁必须**由调用方显式解开**：级联取消时忘了解锁，子节点就再也点不亮了
        （用户只能关掉对话框重开）—— 所以上层用 `force(False)` + `lock(False)`
        成对做，别只做一半。
    ⚠ `on_change(checked: bool)` 在**图标已经翻过来之后**调用；回调里抛异常**不会**
      让勾选卡住（先翻图标、再回调）—— 与「点了没反应」那类 bug 同源，别反过来写。

        English:
    ★ Returns `(control, state)`; `state['checked']` is the single source of truth. Four operations:
        · `state['set'](bool)`   behaves like **a user click** (fires `on_change`; obeys the lock)
        · `state['force'](bool)` **sets the state without firing** (used by cascades)
        · `state['lock'](bool)`  lock/unlock: while locked it **cannot be clicked** and is drawn grey
        · `state['locked']`      whether it is locked right now
    ★★★ Why `lock` exists (user, 2026-10-21: "checking a node's checkbox auto-checks its children,
      and while the parent is checked all child checkboxes are grey and cannot be unchecked. To pick a
      child you must uncheck the parent first."): this is **tree semantics** -- deleting a parent
      inevitably takes every descendant (`TRASH.descendants`), so letting children *look* selectable
      is a lie. Grey = "it will certainly be deleted".
      ⚠ The lock must be **explicitly released by the caller**: forget to unlock during a cascade and
        the child can never be ticked again (the user has to reopen the dialog) -- so the layer above
        always does `force(False)` + `lock(False)` as a pair, never half of it.
    ⚠ `on_change(checked)` is called **after** the icon flipped, so an exception in the callback can
      never leave the tick stuck -- same family as the "clicking does nothing" bug; never invert it.
    """
    icon = ft.Icon(ft.Icons.CHECK_BOX_OUTLINE_BLANK if not checked
                   else ft.Icons.CHECK_BOX,
                   size=SZ(15), color=C['gold'] if checked else C['muted'])
    state = {'checked': bool(checked), 'locked': False}

    def _paint() -> None:
        # ⚠ `ft.Icon` 的字段是 **`icon`**，不是 `name`（见 `_toggle` 那段血泪）
        # [EN] ⚠ `ft.Icon`'s field is **`icon`**, not `name` (see the hard-won note in `_toggle`)
        icon.icon = (ft.Icons.CHECK_BOX if state['checked']
                     else ft.Icons.CHECK_BOX_OUTLINE_BLANK)
        if state['locked']:
            # 锁住 = 灰：与"未勾"的灰**不同一档**（更淡），一眼能分出"能点但没勾"
            # 与"点了也没用"
            # [EN] Locked = grey, one notch fainter than plain "unchecked", so "clickable but
            # [EN] unticked" and "clicking does nothing" are distinguishable at a glance
            icon.color = with_alpha(C['muted'], 0.40)
        else:
            icon.color = C['gold'] if state['checked'] else C['muted']

    def _upd() -> None:
        try:
            icon.update()
        except Exception:                                    # noqa: BLE001
            pass

    def _hit(_e=None):
        if state['locked']:
            return                       # 锁住 ⇒ 点不动（用户点名的行为）
        state['checked'] = not state['checked']
        _paint()
        _upd()
        if on_change:
            try:
                on_change(state['checked'])
            except Exception:                                # noqa: BLE001
                pass

    box = ft.Container(content=icon, width=20, height=22,
                       alignment=ft.Alignment(0, 0), border_radius=4,
                       on_click=_hit, tooltip=(tooltip or None))

    def _set(v: bool) -> None:
        if bool(v) == state['checked'] or state['locked']:
            return
        _hit()

    def _force(v: bool) -> None:
        """**绕过锁、也不回调**地设状态（级联与"全清"用）。"""
        if bool(v) == state['checked']:
            return
        state['checked'] = bool(v)
        _paint()
        _upd()

    def _lock(v: bool) -> None:
        state['locked'] = bool(v)
        _paint()
        _upd()

    state['set'] = _set
    state['force'] = _force
    state['lock'] = _lock
    state['icon'] = icon
    return box, state


def set_btn_text(btn, text: str) -> None:
    """改按钮文字。
    Flet 1.0 里按钮文字在 **`content`**，而不是 `.text`。
    而 `content` 可能是裸字符串（`FilledButton("暂停")` 的第一个位置参数就是它），
    也可能是 `ft.Text` —— 两种都要能改。
    
        English:
    Change button text.
        In Flet 1.0 button text is in **`content`**, not `.text`.
        And `content` may be a bare string (the first positional arg of `FilledButton("Pause")` is it),
        or it may be `ft.Text` -- both must be changeable.
    """
    if btn is None:
        return
    if isinstance(getattr(btn, 'content', None), ft.Text):
        btn.content.value = text
    else:
        btn.content = text


def plot_node_mark(*, done: bool, is_current: bool) -> str:
    """节点前面那个符号：**演过的实心、没演的空心、正在演的三角**。

    用户 2026-10-22 的原话：「当前剧情会被显示出来并且前面的圆圈会变成满的，
    没有上演的剧情前面的圆圈则是空的」。所以：
      · `●` = 已经上演过（实心 = 满）
      · `○` = 还没上演（空心 = 空）
      · `▶` = **正在演的这一站** —— 它不是"满/空"的问题，是"此刻在这一站"，
              留一个和之前一样的三角，用户不用重新学一套记号
      · 已完成优先：走到最后一站时 `advance_node` 会把它标完成，
        这时该显示 `●`（全演完了），不该再留一个"正在"。

    ★ 这是**纯函数**，产品与判据共用同一份 —— 判据要是自己再写一套 if/else，
      迟早出现"判据说实心、界面画空心"。

        English:
    The glyph in front of a node: **filled = already played, hollow = not yet, triangle = on it now**.
    The user's words: "the current plot point gets shown and its circle becomes full, ones not yet
    played have an empty circle". So `●` played, `○` not yet, `▶` the station being played right now
    (not a filled/hollow question -- it is "we are here"), and **done wins**: at the last station
    `advance_node` marks it done, and then `●` is right, not "currently playing".
    ★ A **pure function** shared by the product and the criteria; a second copy of this if/else would
    eventually disagree with the UI.
    """
    if done:
        return '●'
    if is_current:
        return '▶'
    return '○'


def plot_carousel_step(index: int, total: int, delta: int) -> int:
    """跑马灯走一步：`delta` = +1 下一站 / -1 上一站，**到两端循环**。

    ★ 为什么要循环（而不是"到头就停"）：用户要的是"快速查看剧情列表"。
      到最后一站再点右箭头却什么都不发生，会让人以为按钮坏了 ——
      而这里恰好没有一个"外面的位置"可以停（不是翻页，是一个环）。

    ★ `total <= 0` 时**恒返回 0**：没有节点时点按钮不许抛（`% 0` 会 ZeroDivisionError），
      也不许把索引变成负数。

        English:
    One step of the carousel: `delta` = +1 next / -1 previous, **wrapping at both ends**.
    ★ Why wrap instead of stopping at the ends: the point is "quickly browse the list". Hitting the
    right arrow at the last station and having nothing happen reads as a broken button, and there is
    no "outside" position to stop at -- this is a ring, not pagination.
    ★ With `total <= 0` always returns 0: with no nodes a click must not raise (`% 0` is a
    ZeroDivisionError) and must not produce a negative index.
    """
    try:
        n = int(total or 0)
        if n <= 0:
            return 0
        return (int(index or 0) + int(delta or 0)) % n
    except (TypeError, ValueError):                        # noqa: BLE001
        return 0


def plot_carousel_pick(*, sel, manual: bool, total: int, follow: int) -> int:
    """这一帧该显示第几个。

    | 情形 | 显示 |
    |---|---|
    | 没有节点 | 0 |
    | 用户**没手动翻过** | `follow`（跟着真正的当前站走 —— 打开就看到自己在哪） |
    | 手动翻过、但索引越界（节点表变短了） | `follow` |
    | 手动翻过、索引还在范围内 | **保持用户翻到的那个** |

    ★★★ 最后一行是这条功能能不能用的关键：这一块**跟着秒表每秒刷一次**
      （`_refresh_plot_panel` 在 `_tick` 里调）。如果刷新时把索引重置成"当前站"，
      用户翻到第 5 站、一秒后就被拉回第 1 站 —— 表现就是"点了没反应"，
      而按钮、数据、回调全都对。**浏览位置是用户的选择，不能被定时刷新覆盖。**
    ★ 反过来，节点表变短（换了项目 / 回档）时索引会越界，那时必须回到 `follow`，
      否则会 `IndexError` 拿到空标题（界面上是一条空白，看着像"剧情没了"）。

        English:
    Which index to show this frame. No nodes -> 0; never manually browsed -> `follow` (the real
    current station, so opening the panel shows where we are); browsed but the index is out of range
    (the node list shrank) -> `follow`; browsed and still in range -> **keep the user's position**.
    ★★★ That last row is what makes the feature work at all: this block refreshes **every second**
    with the stopwatch (`_refresh_plot_panel` is called from `_tick`). Resetting the index to the
    current station on every refresh would yank the user back a second after they browse to station 5
    -- which looks exactly like "the buttons do nothing", while the buttons, data and callbacks are
    all correct. **The browse position belongs to the user and must not be overwritten by a timer.**
    ★ Conversely, when the node list shrinks (project switch / rollback) the index goes out of range
    and must fall back to `follow`, or indexing raises / yields a blank title, which looks like "the
    plot is gone".
    """
    try:
        n = int(total or 0)
        if n <= 0:
            return 0
        if not manual or sel is None:
            return max(0, min(int(follow or 0), n - 1))
        i = int(sel)
        if i < 0 or i >= n:
            return max(0, min(int(follow or 0), n - 1))
        return i
    except (TypeError, ValueError):                        # noqa: BLE001
        return 0


def plot_wheel_step(e) -> int:
    """鼠标滚轮 → 走几格（-1 上一站 / +1 下一站 / 0 不动）。

    ★ 只取**符号**，不取绝对值：一次滚轮事件可能带几十像素的 delta
      （实测一个 notch 约 53~120），按数值走会一下飞过好几站 ——
      而用户要的是"一格一格快速看"，不是"一跳到底"。
    ★ **抽成纯函数**的理由（和 `plot_node_mark` 一样）：滚轮那一段原来是写在
      建面板的闭包里，判据只能拿夹具上那个 `lambda e: None` 去测 ——
      **测的是夹具自己的空函数**，产品改坏了也绿。现在两边共用这一份，
      测它就是测产品；"有没有真的挂上去"另外用源码判（见判据 H2）。
    ★ 事件形状不认识时返回 0（不动），绝不抛 —— 滚轮是旁路操作，
      不该因为一个异常把整个刷新打断。
    ★ `scroll_delta > 0` = 向下滚 = 下一站。若某个平台把方向反过来，
      用户会立刻看到"滚反了"，那时只改这一行。

        English:
    Mouse wheel -> how many steps (-1 previous / +1 next / 0 stay).
    ★ Only the **sign**, never the value: one wheel event can carry tens of pixels (a notch measured at
      53-120), and stepping by the value would fly past several stations, while the user asked for
      "browse quickly, one at a time".
    ★ **Why a pure function** (same reason as `plot_node_mark`): the wheel handler used to live in a
      closure inside the panel builder, so the criteria could only exercise the fixture's own
      `lambda e: None` -- **measuring the fixture's no-op**, green even if the product broke. Now both
      sides share this one, so testing it tests the product; "is it actually wired up" is judged
      separately from the source (criterion H2).
    ★ Unknown event shapes return 0 (stay), never raise -- the wheel is a side path and must not break
      the refresh.
    ★ `scroll_delta > 0` = scrolled down = next station. If a platform inverts this, the user sees
      "it scrolls backwards" immediately and only this line changes.
    """
    try:
        d = float(getattr(e, 'scroll_delta', 0) or 0)
    except (TypeError, ValueError):
        return 0
    if d > 0:
        return 1
    if d < 0:
        return -1
    return 0


def plot_chip_plan(labels: list[str], width: float = None) -> list[int]:
    """把一串胶囊标签**按宽度分组成几行**，返回每行放几个（例：`[3, 3, 2]`）。

    ★ 这是"剧情面板高度与节点个数无关"的关键那一半，**产品与判据共用同一份**：
      产品拿它决定要不要滚，判据拿它算占几行。两边各写一套估算的话，
      迟早出现"判据说 2 行、界面实际 3 行"。

    ★ 为什么自己分组、不用 `Row(wrap=True)`：
      wrap 的高度由内容算，**没法封顶**；放进定高容器后各平台的滚动行为也不一致。
      自己分组，行数就是确定的、可数的。

    ★ 宽度估算：中文/全角按 **1 个字号宽**，ASCII（符号、数字）按 **半宽**，
      每个胶囊再加左右各 4px 内边距；行内间隔 4px。
      这是估算、不是渲染 ⇒ **判据只判"行数关系"**（≤ 上限、不随节点数增长），
      不判"像素完全相等"。

    ★ 单个标签比整行还宽时**独占一行**（不能返回 0 个，否则会死循环）。

        English:
    Group chip labels into rows by width; returns how many chips per row (`[3, 3, 2]`).
    ★ This is the other half of "the panel height is independent of the node count", **shared by the
    product and the criteria**: the product uses it to decide whether to scroll, the criteria use it
    to count rows. Two separate estimates would eventually disagree.
    ★ Why group by hand instead of `Row(wrap=True)`: wrap's height follows content and **cannot be
    capped**, and inside a fixed-height box its scrolling differs per platform. Grouping by hand makes
    the row count determinate and countable.
    ★ Width estimate: CJK/full-width = **1 em**, ASCII = **half**, plus 4px padding each side per
    chip and 4px between chips. It is an estimate, not rendering -- so criteria only judge **row
    relations**, never exact pixels.
    ★ A label wider than the whole row gets a row to itself (never return 0, or we would loop).
    """
    w_total = float(width if width is not None else PLOT_CHIP_W)
    gap = 4.0
    pads = 8.0                                   # 左右各 4px
    out: list[int] = []
    cur_n = 0
    cur_w = 0.0
    for lb in labels or []:
        lb_w = sum((PLOT_CHIP_FS * 0.5 if ord(ch) < 0x2E80 else PLOT_CHIP_FS)
                   for ch in str(lb)) + pads
        if cur_n and cur_w + gap + lb_w > w_total:
            out.append(cur_n)
            cur_n, cur_w = 1, lb_w
        else:
            cur_w += (gap if cur_n else 0) + lb_w
            cur_n += 1
    if cur_n:
        out.append(cur_n)
    return out


def make_border(width: int = 1, color: str = '#4a3f34') -> ft.Border:
    """创建边框（Flet 1.0 兼容）。
        English:
    Create a border (Flet 1.0 compatible).
    """
    side = ft.BorderSide(width, color)
    return ft.Border(top=side, bottom=side, left=side, right=side)


def make_border_bottom(width: int = 1, color: str = '#4a3f34') -> ft.Border:
    """创建只有底部的边框（Flet 1.0 兼容）。
        English:
    Create a bottom-only border (Flet 1.0 compatible).
    """
    return ft.Border(bottom=ft.BorderSide(width, color))


def make_padding(top: int = 0, right: int = 0, bottom: int = 0, left: int = 0) -> ft.Padding:
    """创建内边距（Flet 1.0 兼容）。
        English:
    Create padding (Flet 1.0 compatible).
    """
    return ft.Padding(left, top, right, bottom)


def make_padding_symmetric(horizontal: int = 0, vertical: int = 0) -> ft.Padding:
    """创建对称内边距（Flet 1.0 兼容）。
        English:
    Create symmetric padding (Flet 1.0 compatible).
    """
    return ft.Padding(horizontal, vertical, horizontal, vertical)


